entries[208229] = { ["name"] = "Seelenschnitter", ["text"] = "Unbegrenzte Reichweite\nSofort\nStößt auf das aktuelle Ziel hinab, trifft es mit 1568 körperlichem Schaden und erzeugt mehrere Schattenmagiebögen, die sich nach außen bewegen. Jeder Bogen schert ein Stück der Seele jedes getroffenen Ziels von seinem Körper ab und stößt dieses Stück auf den Kampfplatz aus. ' Abgeschorene Seele ' absorbiert die gesamte erhaltene Heilung, bis ein anderer Spielercharakter das Stück einsammelt.\n\nWenn die ' Abgeschorene Seele ' eingesammelt wird, fügt sie Zielen innerhalb von 2 Metern 140 Schattenschaden zu, belegt sie mit ' Abgetrennt ' und erhöht den durch ' Abgetrennt ' erlittenen Schaden um 900 %.\n\nSobald das Ziel sein Seelenfragment zurückbekommt, wird es zusätzlich mit ' Abgetrennte Seele ' belegt, wodurch 896 erhaltene Heilung absorbiert wird." }
entries[208230] = { ["name"] = "Festmahl des Blutes", ["text"] = "40 Meter Reichweite\nSofort\nTichondrius markiert einen Spielercharakter, erhöht dessen erlittenen körperlichen Schaden um 50% und beschwört 3 Einheiten unreines Blut, die sich auf das Ziel fixieren. Zusätzlich erhöht dieser Effekt den Effekt von 'Vampiraura' um 300%." }
