entries[208350] = { ["name"] = "Seidengewebte Handschuhe", ["text"] = "Wirken in 2 sek.\nReagenzien:\nShal'doreiseide (12), Runenfaden aus Katgut (3)\nOptionale Reagenzien:\n[] (#49)\nVerringert erheblich die erforderlichen Materialien zur Herstellung seidengewebter Handschuhe.\nWeltquest:\nArbeitsauftrag: Seidengewebte Handschuhe\nZone:\nVal'sharah\n\nSeidengewebte Handschuhe\nWird beim Anlegen gebunden\nHände Stoff\n3 Rüstung\n+4 Intelligenz\n+6 Ausdauer\nHaltbarkeit 50 / 50\n44" }
entries[208351] = { ["name"] = "Seidengewebte Kapuze", ["text"] = "Wirken in 2 sek.\nReagenzien:\nShal'doreiseide (16), Runenfaden aus Katgut , Scharfer Waldgeistdorn\nOptionale Reagenzien:\n[] (#48)\nVerringert erheblich die erforderlichen Materialien zur Herstellung einer seidengewebten Kapuze.\nWeltquest:\nArbeitsauftrag: Seidengewebte Kapuze\nZone:\nDalaran\n\nSeidengewebte Kapuze\nWird beim Anlegen gebunden\nKopf Stoff\n4 Rüstung\n+5 Intelligenz\n+7 Ausdauer\nHaltbarkeit 85 / 85\n44" }
