entries[208802] = { ["name"] = "Seelenkorrosion", ["text"] = "Unbegrenzte Reichweite\nSofort\nFür alle 3 Sek., die ein Spielercharakter im Brunnen der Seelen verbleibt, verlässt ein Seelenfragment den Brunnen, das 4805 Schattenschaden innerhalb von 5 Metern um den anvisierten Spielercharakter verursacht und ihn mit 'Seelenkorrosion' belegt.\n\n'Seelenkorrosion' verursacht 3 Min. lang pro Sekunde 790 Schattenschaden. Dieser Effekt ist stapelbar." }
