entries[208806] = { ["name"] = "Schwarze Ernte", ["text"] = "Sofort\nRuft die Schwarze Ernte, die alle 2 Sek. 19282 Schattenschaden verursacht und alle im Brunnen der Seelen gespeicherten Seelen im Verlauf von 4 Sek. ausstößt. Jede geerntete Seele ruft eine heftige Explosion hervor, die allen Gegnern 11854 Schattenschaden zufügt.\n\nWenn der Brunnen der Seelen voll ist, rufen neu hereingezogene Seelen sofort eine Explosion der geernteten Seelen hervor." }
